sys_script_client.script:
function onSubmit() {

    var name = g_form.getValue('emergency_contact_name');
    var phone = g_form.getValue('emergency_contact_phone');
    var relationship = g_form.getValue('emergency_contact_relationship');

    var hasName = !!name;
    var hasPhone = !!phone;
    var hasRelationship = !!relationship;

    /*
     * If no emergency contact information was entered,
     * allow submission.
     */
    if (!hasName && !hasPhone && !hasRelationship) {
        return true;
    }

    /*
     * Emergency contact name is required
     * when any emergency contact information exists.
     */
    if (!hasName) {

        g_form.showFieldMsg(
            'emergency_contact_name',
            'Emergency Contact Name is required when emergency contact information is provided.',
            'error'
        );

        return false;
    }

    /*
     * Emergency contact phone is required.
     */
    if (!hasPhone) {

        g_form.showFieldMsg(
            'emergency_contact_phone',
            'Emergency Contact Phone is required.',
            'error'
        );

        return false;
    }

    /*
     * Emergency contact relationship is required.
     */
    if (!hasRelationship) {

        g_form.showFieldMsg(
            'emergency_contact_relationship',
            'Emergency Contact Relationship is required.',
            'error'
        );

        return false;
    }

    return true;
}
